import { DateTime } from "luxon";
import type { ReservationRow } from "./booking/reservations";
import { maskEmail, maskPhone } from "./booking/search";

export type ReservationView = {
  id: string; reference: string; status: string; source: string; partySize: number;
  startsAt: string; endsAt: string; date: string; time: string; endTime: string;
  customerId: string; customerName: string; email: string | null; phone: string | null;
  service: string; resource: string; notes: string;
  checkedInAt: string | null; createdAt: string; ticketStatus: string | null;
};

/** The shape sent to staff browsers. Contact details are masked unless the role may see them. */
export function presentReservation(r: ReservationRow, tz: string, fullContact: boolean): ReservationView {
  const s = DateTime.fromJSDate(r.starts_at, { zone: tz });
  const e = DateTime.fromJSDate(r.ends_at, { zone: tz });
  return {
    id: r.id, reference: r.reference, status: r.status, source: r.source, partySize: r.party_size,
    startsAt: r.starts_at.toISOString(), endsAt: r.ends_at.toISOString(),
    date: s.toISODate()!, time: s.toFormat("HH:mm"), endTime: e.toFormat("HH:mm"),
    customerId: r.customer_id, customerName: r.customer_name,
    email: maskEmail(r.customer_email, fullContact), phone: maskPhone(r.customer_phone, fullContact),
    service: r.service_name, resource: r.resource_name, notes: r.notes,
    checkedInAt: r.checked_in_at?.toISOString() ?? null, createdAt: r.created_at.toISOString(), ticketStatus: r.ticket_status,
  };
}
