import Link from "next/link";
import type { ReservationView } from "@/lib/present";
import { SourceTag, StatusBadge } from "./ui";

/** One line of the arrivals board: the time is the thing staff scan for, so it leads. */
export function ReservationRow({ r, slug, showDate }: { r: ReservationView; slug: string; showDate?: boolean }) {
  const dim = r.status === "cancelled" || r.status === "no_show";
  return (
    <li>
      <Link href={`/app/${slug}/reservations/${r.id}`} data-testid="reservation-row" data-status={r.status}
        className={`flex items-center gap-3 px-4 py-3 hover:bg-paper sm:gap-5 ${dim ? "opacity-60" : ""}`}>
        <div className="w-[4.6rem] shrink-0">
          <p className="font-display text-2xl leading-none font-extrabold tabular">{r.time}</p>
          {showDate && <p className="mt-1 text-[13px] text-muted tabular">{new Date(`${r.date}T12:00:00Z`).toLocaleDateString("en-GB", { weekday: "short", day: "numeric", month: "short", timeZone: "UTC" })}</p>}
        </div>
        <div className="min-w-0 flex-1">
          <p className={`truncate text-[17px] font-semibold ${dim ? "line-through" : ""}`}>{r.customerName}</p>
          <p className="truncate text-[14px] text-ink-soft">
            {r.partySize} {r.partySize === 1 ? "guest" : "guests"}, {r.resource}
            {r.notes ? <span className="text-amber"> — {r.notes}</span> : null}
          </p>
        </div>
        <div className="hidden text-right sm:block">
          <p className="font-semibold tracking-wider tabular">{r.reference}</p>
          <SourceTag source={r.source} />
        </div>
        <StatusBadge status={r.status} />
      </Link>
    </li>
  );
}
