import { q, type Db } from "./db";

export async function audit(
  entry: { businessId: string | null; userId: string | null; action: string; entity?: string; entityId?: string; detail?: Record<string, unknown> },
  db?: Db,
) {
  await q(
    "INSERT INTO audit_logs (business_id, user_id, action, entity, entity_id, detail) VALUES ($1,$2,$3,$4,$5,$6)",
    [entry.businessId, entry.userId, entry.action, entry.entity ?? "", entry.entityId ?? "", JSON.stringify(entry.detail ?? {})],
    db,
  );
}

/** Structured server log. Never pass passwords, tokens or customer contact details. */
export function log(level: "info" | "warn" | "error", msg: string, fields: Record<string, unknown> = {}) {
  const line = JSON.stringify({ t: new Date().toISOString(), level, msg, ...fields });
  if (level === "error") console.error(line);
  else console.log(line);
}
