import Link from "next/link";
import QRCode from "qrcode";
import { can } from "@/lib/auth";
import { listReservations } from "@/lib/booking/search";
import { pageMember } from "@/lib/page";
import { presentReservation } from "@/lib/present";
import { env } from "@/lib/env";
import { fmtDateLong, todayIn } from "@/lib/time";
import { Card } from "@/components/ui";
import { ReservationRow } from "@/components/ReservationRow";
import { CopyLink } from "@/components/CopyLink";

export const metadata = { title: "Today" };

export default async function TodayPage({ params, searchParams }: { params: Promise<{ slug: string }>; searchParams: Promise<{ welcome?: string }> }) {
  const { slug } = await params;
  const { business, role } = await pageMember(slug);
  const today = todayIn(business.timezone);
  const { rows } = await listReservations(business.id, business.timezone, { from: today, to: today, limit: 200 });
  const list = rows.map((r) => presentReservation(r, business.timezone, can(role, "customers.full")));
  const now = Date.now();
  const live = list.filter((r) => !["cancelled", "no_show"].includes(r.status));
  const upcoming = list.filter((r) => ["confirmed", "pending"].includes(r.status) && new Date(r.startsAt).getTime() > now - 30 * 60_000);
  const arrived = list.filter((r) => ["checked_in", "completed"].includes(r.status));
  const rest = list.filter((r) => !upcoming.includes(r) && !arrived.includes(r));
  const guests = live.reduce((n, r) => n + r.partySize, 0);
  const bookingUrl = `${env.appUrl}/b/${business.slug}`;
  const qr = await QRCode.toString(bookingUrl, { type: "svg", margin: 1, color: { dark: "#0b1f4b", light: "#ffffff" } });
  const welcome = (await searchParams).welcome;

  return (
    <div className="space-y-5">
      {welcome && (
        <div className="rounded-2xl bg-mint-soft px-5 py-4 ring-1 ring-mint/40">
          <p className="font-display text-lg font-bold">Your business is ready.</p>
          <p className="text-ink-soft">Share the booking link below with customers, or open it yourself to try a booking. Add FAQs and policies in Settings so the assistant can answer more questions.</p>
        </div>
      )}
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h1 className="text-3xl font-extrabold">Today</h1>
          <p className="text-ink-soft">{fmtDateLong(new Date(), business.timezone)}</p>
        </div>
        <div className="flex gap-2">
          <Link href={`/app/${slug}/checkin`} className="inline-flex min-h-11 items-center rounded-xl bg-mint px-4 font-semibold text-white">Scan a ticket</Link>
          <Link href={`/app/${slug}/new`} className="inline-flex min-h-11 items-center rounded-xl bg-brand px-4 font-semibold text-white">Add reservation</Link>
        </div>
      </div>

      <p className="text-[17px]" data-testid="today-summary">
        <strong>{live.length}</strong> {live.length === 1 ? "reservation" : "reservations"}, <strong>{guests}</strong> {guests === 1 ? "guest" : "guests"} expected, <strong>{arrived.length}</strong> arrived.
      </p>

      {list.length === 0 ? (
        <Card className="px-6 py-10 text-center">
          <p className="font-display text-xl font-bold">No reservations today yet</p>
          <p className="mx-auto mt-1 max-w-sm text-ink-soft">New bookings appear here on their own. Share your booking link, or add one for a customer who called.</p>
        </Card>
      ) : (
        <>
          <Section title="Next arrivals" empty="Nobody else is due today." items={upcoming} slug={slug} />
          {arrived.length > 0 && <Section title="Arrived" items={arrived} slug={slug} />}
          {rest.length > 0 && <Section title="Earlier, cancelled and no-shows" items={rest} slug={slug} />}
        </>
      )}

      <Card className="flex flex-col gap-4 p-5 sm:flex-row sm:items-center">
        <div className="size-28 shrink-0 rounded-xl bg-white p-1.5 ring-1 ring-line" role="img" aria-label="QR code that opens your booking page" dangerouslySetInnerHTML={{ __html: qr }} />
        <div className="min-w-0 flex-1">
          <h2 className="text-lg font-bold">Your booking page</h2>
          <p className="text-[15px] text-ink-soft">Put this link on your website, social profiles or a table card. Customers chat with the assistant or use the form.</p>
          <CopyLink url={bookingUrl} />
        </div>
      </Card>
    </div>
  );
}

function Section({ title, items, slug, empty }: { title: string; items: ReturnType<typeof presentReservation>[]; slug: string; empty?: string }) {
  return (
    <section>
      <h2 className="mb-2 text-lg font-bold">{title} <span className="font-sans text-base font-medium text-muted">{items.length}</span></h2>
      <Card>
        {items.length === 0 ? <p className="px-4 py-4 text-ink-soft">{empty}</p> : <ul className="divide-y divide-line">{items.map((r) => <ReservationRow key={r.id} r={r} slug={slug} />)}</ul>}
      </Card>
    </section>
  );
}
